package io.knowledgebrain.content;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;
import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_CONTENT_DATABASE_URL",matches=".+")
class BookmarkStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;BookmarkStore store;String schema;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;String trace="e".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_CONTENT_DATABASE_URL"));ds.setUser("brain_content");ds.setPassword(System.getenv("BRAIN_TEST_CONTENT_DATABASE_PASSWORD"));schema="bookmark_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new BookmarkStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 BookmarkStore.Input input(String title){return new BookmarkStore.Input(title,"https://example.test/a?x=One%2FTwo#anchor"," \n\tplain memo\r\n ");}
 BookmarkStore.Bookmark create(){return store.create(space,actor,key(),input("Saved title"),trace).bookmark();}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 @Test void createRetriesReplayOriginalSnapshotAfterEditingArchivalAndPrincipalChange(){var key=key();var first=store.create(space,actor,key,input("First"),trace);assertFalse(first.replay());var v=first.bookmark();store.change(space,v.bookmarkId(),actor,1,input("Later"),false,trace);store.change(space,v.bookmarkId(),actor,2,null,true,trace);var replay=store.create(space,ids.next(),key,input("First"),trace);assertTrue(replay.replay());assertEquals(v,replay.bookmark());status(409,()->store.create(space,actor,key,input("Different"),trace));assertEquals(1,count("bookmark"));assertEquals(3,count("bookmark_revision"));assertEquals(3,count("outbox_event"));assertEquals(actor,store.history(space,v.bookmarkId(),Long.MAX_VALUE,10).getLast().actorId());}
 @Test void independentStrongVersionsNoopAndRetiredHistorySurviveNewStore(){var v=create();for(int n=1;n<=6;n++)v=store.change(space,v.bookmarkId(),actor,n,input("Update "+n),false,trace);var id=v.bookmarkId();assertEquals(v,store.change(space,id,actor,7,input("Update 6"),false,trace));status(412,()->store.change(space,id,actor,1,input("Update 6"),false,trace));assertEquals(List.of(7L,6L,5L,4L,3L),store.history(space,id,Long.MAX_VALUE,5).stream().map(BookmarkStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(space,id,3,5).stream().map(BookmarkStore.Revision::version).toList());var retired=store.change(space,id,actor,7,null,true,trace);assertEquals(retired,new BookmarkStore(ds,Clock.systemUTC()).get(space,id));assertEquals(retired,store.change(space,id,actor,8,null,true,trace));status(404,()->store.change(space,id,actor,8,input("Blocked"),false,trace));assertEquals(8,count("bookmark_revision"));}
 @Test void controlledOutboxFailureRollsBackCreationAndMutationIncludingKeys(){sql.execute("CREATE FUNCTION fail_bookmark() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled bookmark failure'; END $$");sql.execute("CREATE TRIGGER fail_bookmark BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_bookmark()");var key=key();assertThrows(RuntimeException.class,()->store.create(space,actor,key,input("Rollback"),trace));assertEquals(0,count("bookmark"));assertEquals(0,count("bookmark_revision"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_bookmark");var v=store.create(space,actor,key,input("Rollback"),trace).bookmark();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_bookmark");assertThrows(RuntimeException.class,()->store.change(space,v.bookmarkId(),actor,1,input("Lost"),false,trace));assertEquals(v,store.get(space,v.bookmarkId()));assertEquals(1,count("bookmark_revision"));}
 @Test void concurrentCreateAndEditsHaveOneCanonicalOutcome()throws Exception{var key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);Callable<BookmarkStore.Created> task=()->{gate.await();return store.create(space,actor,key,input("Concurrent"),trace);};var a=pool.submit(task);var b=pool.submit(task);var x=a.get();var y=b.get();assertEquals(x.bookmark(),y.bookmark());assertNotEquals(x.replay(),y.replay());var id=x.bookmark().bookmarkId();var gate2=new CyclicBarrier(2);Callable<Integer> write=()->{gate2.await();try{store.change(space,id,actor,1,input("Winner"),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}};var c=pool.submit(write);var e=pool.submit(write);assertEquals(Set.of(200,412),Set.of(c.get(),e.get()));}assertEquals(1,count("bookmark"));assertEquals(2,count("outbox_event"));}
 @Test void duplicateUrlsKeepDistinctIdsAndCursorPagesCannotCrossSpaceOrLifecycle(){for(int n=0;n<23;n++)create();var a=store.list(space,"ACTIVE",null,20);var b=store.list(space,"ACTIVE",a.nextAfter(),20);assertEquals(20,a.items().size());assertEquals(3,b.items().size());assertNull(b.nextAfter());assertEquals(23,a.items().stream().map(BookmarkStore.Summary::bookmarkId).distinct().count()+b.items().stream().map(BookmarkStore.Summary::bookmarkId).distinct().count());status(400,()->store.list(actor,"ACTIVE",a.nextAfter(),20));status(400,()->store.list(space,"RETIRED",a.nextAfter(),20));status(404,()->store.get(actor,a.items().getFirst().bookmarkId()));assertTrue(store.list(actor,"ACTIVE",null,20).items().isEmpty());}
 @Test void bookmarkWritesKeepExistingNoteContentAndEventsIndependent(){var notes=new NoteStore(ds,Clock.systemUTC());var note=notes.create(space,actor,"Own note","Unchanged markdown",trace);var v=create();store.change(space,v.bookmarkId(),actor,1,input("Edit only bookmark"),false,trace);assertEquals(note,notes.get(space,note.noteId()));assertEquals(1,notes.history(space,note.noteId(),Long.MAX_VALUE,10).size());assertEquals(2,sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='bookmark'",Integer.class));}
}
